const data = $input.first().json.body || $input.first().json;
const { tenant, objective, vibe, platforms, startDate, endDate, frequency, contentMix, businessContext, platformLimits, platformGuidance } = data;

const objectiveLabels = {
  sales: 'Ventas y conversiones',
  brand: 'Imagen de marca',
  educational: 'Educativo',
  engagement: 'Engagement'
};

const vibeLabels = {
  professional: 'Profesional',
  casual: 'Casual',
  funny: 'Divertido',
  inspiring: 'Inspirador'
};

const start = new Date(startDate);
const end = new Date(endDate);
const daysDiff = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
const weeks = daysDiff / 7;
const totalPosts = Math.floor(weeks * (frequency?.postsPerWeek || 3));
const totalReels = Math.floor(weeks * (frequency?.reelsPerWeek || 1));
const totalStories = Math.floor(weeks * (frequency?.storiesPerWeek || 2));
const totalContent = totalPosts + totalReels + totalStories;

const platformList = Array.isArray(platforms) ? platforms.join(', ') : platforms;
const guidanceText = (platforms || []).map(p => {
  const limit = platformLimits?.[p] || 2200;
  const guide = platformGuidance?.[p] || '';
  return `- ${p}: máximo ${limit} caracteres. ${guide}`;
}).join('\n');

const systemPrompt = `Eres un experto en marketing de redes sociales para pequeños negocios en México y Latinoamérica. Genera contenido atractivo, auténtico y listo para publicar. Responde SOLO con JSON válido, sin texto extra, sin markdown, sin bloques de código.`;

const userPrompt = `Negocio: ${tenant}
Objetivo: ${objectiveLabels[objective] || objective}
Tono: ${vibeLabels[vibe] || vibe}
Plataformas: ${platformList}
Contexto del negocio: ${businessContext || 'Negocio local'}

Distribución de contenido:
- Promocional: ${contentMix?.promotions || 40}%
- Antes/Después: ${contentMix?.before_after || 30}%
- Tendencias: ${contentMix?.trends || 20}%
- Tips: ${contentMix?.tips || 10}%

Genera ${totalContent} piezas de contenido distribuidas en:
- ${totalPosts} posts
- ${totalReels} reels
- ${totalStories} stories

Para cada pieza devuelve este JSON exacto (sin markdown):
[
  {
    "title": "título corto máximo 60 caracteres",
    "content": "texto principal adaptado a cada plataforma",
    "platforms": ["facebook", "instagram"],
    "format": "post|reel|story",
    "suggestedTime": "morning|afternoon|evening",
    "contentType": "promotional|before_after|trending|tip"
  }
]

Reglas por plataforma:
${guidanceText}

- Usa emojis con moderación
- Incluye calls-to-action cuando apliquen
- No repitas ideas
- Adapta el tono a cada plataforma dentro del mismo contenido`};

return [{
  json: {
    ollamaBody: {
      model: $env.OLLAMA_MODEL || 'llama3.2',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      stream: false,
      temperature: 0.8
    },
    originalData: data,
    totalContent
  }
}];

const ollamaResponse = $input.first().json;
const originalData = $('Build Ollama Prompt').first().json.originalData;

let generatedContent = [];
try {
  const rawContent = ollamaResponse.choices?.[0]?.message?.content || ollamaResponse.message?.content || ollamaResponse.content || '';
  const cleaned = rawContent
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();
  const jsonMatch = cleaned.match(/\[[\s\S]*\]/);
  generatedContent = JSON.parse(jsonMatch ? jsonMatch[0] : cleaned);
} catch (parseError) {
  return [{
    json: {
      success: false,
      error: 'No se pudo generar contenido. Intenta de nuevo.',
      details: parseError.message
    }
  }];
}

const totalContent = $('Build Ollama Prompt').first().json.totalContent || generatedContent.length;
const start = new Date(originalData.startDate);
const end = new Date(originalData.endDate);
const daysDiff = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
const timeMap = { morning: 9, afternoon: 14, evening: 19 };

const formattedPosts = generatedContent.map((item, index) => {
  const dayOffset = Math.floor((index / Math.max(totalContent, 1)) * daysDiff);
  const postDate = new Date(start);
  postDate.setDate(postDate.getDate() + dayOffset);
  postDate.setHours(timeMap[item.suggestedTime] || 12, 0, 0, 0);

  const validPlatforms = (item.platforms || []).filter(p => (originalData.platforms || []).includes(p));
  const finalPlatforms = validPlatforms.length > 0 ? validPlatforms : (originalData.platforms || []);

  return {
    id: `ai-generated-${index}`,
    title: (item.title || `Post ${index + 1}`).slice(0, 60),
    content: item.content || '',
    platforms: finalPlatforms,
    format: ['post', 'reel', 'story'].includes(item.format) ? item.format : 'post',
    scheduledAt: postDate.toISOString(),
    status: 'draft',
    contentType: ['promotional', 'before_after', 'trending', 'tip'].includes(item.contentType) ? item.contentType : 'promotional'
  };
});

formattedPosts.sort((a, b) => new Date(a.scheduledAt) - new Date(b.scheduledAt));

return [{
  json: {
    success: true,
    data: {
      generatedPosts: formattedPosts,
      summary: {
        totalPosts: formattedPosts.length,
        postsByFormat: {
          post: formattedPosts.filter(p => p.format === 'post').length,
          reel: formattedPosts.filter(p => p.format === 'reel').length,
          story: formattedPosts.filter(p => p.format === 'story').length
        },
        postsByType: {
          promotional: formattedPosts.filter(p => p.contentType === 'promotional').length,
          before_after: formattedPosts.filter(p => p.contentType === 'before_after').length,
          trending: formattedPosts.filter(p => p.contentType === 'trending').length,
          tip: formattedPosts.filter(p => p.contentType === 'tip').length
        },
        dateRange: {
          start: originalData.startDate,
          end: originalData.endDate
        }
      }
    }
  }
}];
